import{H as e,_t as t,nt as n,rt as r}from"./chunks/framework.ByJSXnli.js";var i=JSON.parse(`{"title":"Analyzers and traces","description":"","frontmatter":{},"headers":[],"relativePath":"reference/analyzers.md","filePath":"reference/analyzers.md"}`),a={name:`reference/analyzers.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="analyzers-and-traces" tabindex="-1">Analyzers and traces <a class="header-anchor" href="#analyzers-and-traces" aria-label="Permalink to “Analyzers and traces”">​</a></h1><p>The analysis building blocks of the core package. <a href="/guide/execution/observability-and-analysis.html">Analysis of algorithm runs</a> shows how to place them and read their results.</p><h2 id="observation-sources" tabindex="-1">Observation sources <a class="header-anchor" href="#observation-sources" aria-label="Permalink to “Observation sources”">​</a></h2><p>A source names a boundary to observe. Creating one installs nothing.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Source</th><th>Observes</th><th>Observation</th></tr></thead><tbody><tr><td><code>operator.Invocations</code></td><td>Each successful call of the operator</td><td>The operation&#39;s record, such as <code>MutationObservation&lt;T&gt;</code></td></tr><tr><td><code>algorithm.Iterations</code></td><td>Each state the algorithm yields, after interceptors</td><td><code>AlgorithmObservation&lt;T, TState&gt;</code></td></tr><tr><td><code>algorithm.Calls</code></td><td>The start and outcome of each executor call</td><td><code>AlgorithmCallObservation&lt;T, TState&gt;</code></td></tr></tbody></table></div><p>Every operation offers <code>Invocations</code>, including operations you <a href="/extend/defining-operations.html">define</a>.</p><h2 id="analyzers" tabindex="-1">Analyzers <a class="header-anchor" href="#analyzers" aria-label="Permalink to “Analyzers”">​</a></h2><p>Pass an analyzer to <code>CreateRun</code> and read its result with <code>run.Result(analyzer)</code>.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Analyzer</th><th>Records</th><th>Result</th></tr></thead><tbody><tr><td><code>Analyzer.BestSoFar&lt;T&gt;()</code></td><td>The running best candidate at the innermost evaluators</td><td><code>BestSoFarCurve&lt;T&gt;</code></td></tr><tr><td><code>Analyzer.BestSoFar(evaluator)</code></td><td>The running best candidate at one evaluator</td><td><code>BestSoFarCurve&lt;T&gt;</code></td></tr><tr><td><code>algorithm.Iterations.TracePopulationQuality()</code></td><td>Best, median and worst objective vector of each yielded population</td><td><code>Trace&lt;BestMedianWorst&gt;</code></td></tr><tr><td><code>algorithm.Iterations.TracePopulationCandidates()</code></td><td>Best, median and worst candidate of each yielded population</td><td><code>Trace&lt;BestMedianWorstEntry&lt;T&gt;&gt;</code></td></tr><tr><td><code>source.Trace(value)</code> or <code>Analyzer.Trace(sources, value)</code></td><td>One value per observation</td><td><code>Trace&lt;TValue&gt;</code></td></tr><tr><td><code>source.Aggregate(create, update)</code> or <code>Analyzer.Aggregate(sources, create, update)</code></td><td>One state updated by every observation</td><td>The state you create</td></tr></tbody></table></div><p>Each trace and best-so-far analyzer takes optional <code>clocks</code> and <code>retention</code> arguments. A best-so-far curve point carries its <code>Evaluations</code>, <code>Value</code> and <code>Candidate</code>. A trace offers <code>SampleCount</code>, <code>Latest</code>, <code>Snapshot()</code> and <code>By(clock)</code>.</p><h2 id="clocks" tabindex="-1">Clocks <a class="header-anchor" href="#clocks" aria-label="Permalink to “Clocks”">​</a></h2><p>A clock gives each recorded entry its time. Pass clocks in the <code>clocks</code> argument of a trace.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Clock</th><th>Reads</th></tr></thead><tbody><tr><td><code>counter.Clock</code></td><td>The count of a <code>Counter</code></td></tr><tr><td><code>duration.Clock</code></td><td>The time of a <code>Duration</code></td></tr><tr><td><code>Clock.Elapsed</code></td><td>The time the run spends advancing its algorithm</td></tr></tbody></table></div><h2 id="counting-and-timing" tabindex="-1">Counting and timing <a class="header-anchor" href="#counting-and-timing" aria-label="Permalink to “Counting and timing”">​</a></h2><p>Counters and durations record nothing until a placement updates them. Pass the placement to <code>CreateRun</code> or <code>Substitute</code>, after the analyzers that read it.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Placement</th><th>Updates</th></tr></thead><tbody><tr><td><code>source.Counting(counter)</code></td><td>Counts the observations of a source</td></tr><tr><td><code>source.CountingCandidates(counter)</code></td><td>Counts the candidates of an operator&#39;s calls</td></tr><tr><td><code>source.Timing(duration)</code></td><td>Adds the time of an operator&#39;s calls</td></tr><tr><td><code>algorithm.Timed(duration)</code></td><td>Adds the time of an algorithm&#39;s calls</td></tr><tr><td><code>source.Observing(callback)</code></td><td>Passes each observation to a callback</td></tr></tbody></table></div><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to “Retention”">​</a></h2><p>Retention decides which computed values a trace keeps.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Retention</th><th>Keeps</th></tr></thead><tbody><tr><td><code>TraceRetention.EveryObservation()</code></td><td>Every value, the default for traces</td></tr><tr><td><code>TraceRetention.OnChange()</code></td><td>A value that differs from the previous one, the default for best-so-far</td></tr><tr><td><code>TraceRetention.EveryNth(n)</code></td><td>Every n-th value</td></tr><tr><td><code>TraceRetention.LatestOnly()</code></td><td>Only the latest value</td></tr></tbody></table></div>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};